use std::fs

fn height(l: Vec<int>, r: Vec<int>, n: int) -> int {
    if n < 0 { return 0 }
    let a = height(l.clone(), r.clone(), l[n as usize])
    let b = height(l.clone(), r.clone(), r[n as usize])
    if a > b { a + 1 } else { b + 1 }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lc: Vec<int> = []
    let mut rc: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0].clone()
        let mut x: int = 0
        if parts.len() > 1 { x = parts[1].parse::<int>().unwrap_or(0) }
        if cmd == "insert" {
            if root < 0 {
                keys.push(x)
                lc.push(-1)
                rc.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur = root
                let mut done = false
                while !done {
                    let k = keys[cur as usize]
                    if x == k {
                        println("dup")
                        done = true
                    } else if x < k {
                        let nx = lc[cur as usize]
                        if nx < 0 {
                            let id = keys.len() as int
                            keys.push(x)
                            lc.push(-1)
                            rc.push(-1)
                            lc[cur as usize] = id
                            println("ok")
                            done = true
                        } else { cur = nx }
                    } else {
                        let nx = rc[cur as usize]
                        if nx < 0 {
                            let id = keys.len() as int
                            keys.push(x)
                            lc.push(-1)
                            rc.push(-1)
                            rc[cur as usize] = id
                            println("ok")
                            done = true
                        } else { cur = nx }
                    }
                }
            }
        } else if cmd == "contains" {
            let mut cur = root
            let mut found = false
            while cur >= 0 && !found {
                let k = keys[cur as usize]
                if x == k { found = true }
                else if x < k { cur = lc[cur as usize] }
                else { cur = rc[cur as usize] }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let mut cur = root
            let mut par: int = -1
            let mut found = false
            while cur >= 0 && !found {
                let k = keys[cur as usize]
                if x == k { found = true }
                else {
                    par = cur
                    if x < k { cur = lc[cur as usize] } else { cur = rc[cur as usize] }
                }
            }
            if !found {
                println("missing")
            } else {
                let l = lc[cur as usize]
                let r = rc[cur as usize]
                if l >= 0 && r >= 0 {
                    let mut sp = cur
                    let mut s = r
                    while lc[s as usize] >= 0 {
                        sp = s
                        s = lc[s as usize]
                    }
                    keys[cur as usize] = keys[s as usize]
                    if sp == cur { rc[sp as usize] = rc[s as usize] }
                    else { lc[sp as usize] = rc[s as usize] }
                } else {
                    let child = if l >= 0 { l } else { r }
                    if par < 0 { root = child }
                    else if lc[par as usize] == cur { lc[par as usize] = child }
                    else { rc[par as usize] = child }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root < 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<int> = []
                let mut cur = root
                while cur >= 0 || stack.len() > 0 {
                    while cur >= 0 {
                        stack.push(cur)
                        cur = lc[cur as usize]
                    }
                    let n = stack.pop() ?? 0
                    out.push(keys[n as usize].to_string())
                    cur = rc[n as usize]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            println("${height(lc.clone(), rc.clone(), root)}")
        } else if cmd == "min" {
            if root < 0 { println("empty") } else {
                let mut cur = root
                while lc[cur as usize] >= 0 { cur = lc[cur as usize] }
                println("${keys[cur as usize]}")
            }
        } else if cmd == "max" {
            if root < 0 { println("empty") } else {
                let mut cur = root
                while rc[cur as usize] >= 0 { cur = rc[cur as usize] }
                println("${keys[cur as usize]}")
            }
        }
    }
}

